using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using ReFix.Hub;
using ReFix.Updating;
public static class UpdateTests {
 public static void Run(Action<string,bool> report){string root=Path.Combine(Path.GetFullPath("artifacts"),"update-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Action<string,Action> test=(name,body)=>{try{body();report(name,true);}catch(Exception e){Console.WriteLine(e);report(name,false);}};
  try{UpdateNetworkTests.Run(report);
   test("apply rejects foreign ownership and changed parent before writing restart visibility",()=>{var p=Fixture(root,"updates");string path=Path.Combine(p.Work,"plan.json");File.WriteAllText(path,UpdateEngine.Json().Serialize(p));string before=File.ReadAllText(path);var prepared=new PreparedHubUpdate{PlanPath=path};foreach(string app in new[]{Path.Combine(root,"foreign-app"),p.Target}){var service=new HubUpdateService(root,app);Reject(()=>service.StartApply(prepared,true));if(File.ReadAllText(path)!=before||UpdateEngine.LoadPlan(path).RestartInBackground)throw new Exception("Rejected update changed its restart plan");}});
   test("latest restart visibility overrides prepared state and omitted override retains it",()=>{var p=Fixture(root,"refresh-visibility");string path=Path.Combine(p.Work,"plan.json");File.WriteAllText(path,UpdateEngine.Json().Serialize(p));foreach(bool hidden in new[]{true,false,true}){UpdateEngine.SaveRestartMode(p,path,hidden);if(UpdateEngine.LoadPlan(path).RestartInBackground!=hidden)throw new Exception("Latest visibility was not persisted");}UpdateEngine.SaveRestartMode(p,path,null);if(!UpdateEngine.LoadPlan(path).RestartInBackground)throw new Exception("Omitted override discarded prepared visibility");string before=File.ReadAllText(path);Reject(()=>UpdateEngine.SaveRestartMode(p,Path.Combine(p.Work,"other.json"),false));if(File.ReadAllText(path)!=before||File.Exists(Path.Combine(p.Work,"other.json")))throw new Exception("Unvalidated plan path was written");});
   test("update plan preserves hidden and visible restart mode through disk serialization",()=>{foreach(bool hidden in new[]{false,true}){var p=Fixture(root,"visibility-"+hidden);p.RestartInBackground=hidden;string path=Path.Combine(p.Work,"plan.json");File.WriteAllText(path,UpdateEngine.Json().Serialize(p));var loaded=UpdateEngine.LoadPlan(path);if(loaded.RestartInBackground!=hidden)throw new Exception("Restart mode was lost");}});
   test("legacy update plans restart visibly and hidden plans pass background argument",()=>{var p=Fixture(root,"restart-visibility");var json=UpdateEngine.Json().Deserialize<Dictionary<string,object>>(UpdateEngine.Json().Serialize(p));json.Remove("RestartInBackground");string path=Path.Combine(p.Work,"plan.json");File.WriteAllText(path,UpdateEngine.Json().Serialize(json));var legacy=UpdateEngine.LoadPlan(path);if(legacy.RestartInBackground)throw new Exception("Legacy plan unexpectedly starts hidden");foreach(bool hidden in new[]{false,true}){legacy.RestartInBackground=hidden;var info=UpdateEngine.RestartStartInfo(legacy);if(info.FileName!=Path.Combine(p.Target,"HUB-ReFIX.exe")||info.WorkingDirectory!=p.Target||!info.UseShellExecute||info.Arguments!=(hidden?"--background":""))throw new Exception("Incorrect restart executable, directory or visibility argument");}});
   test("network update JSON accepts UTF8 BOM from Windows packaging",()=>{string json=UpdateEngine.Json().Serialize(Release(new string('a',64)));byte[] plain=System.Text.Encoding.UTF8.GetBytes(json),bom=System.Text.Encoding.UTF8.GetPreamble().Concat(plain).ToArray();foreach(byte[] bytes in new[]{plain,bom}){var release=UpdateEngine.Json().Deserialize<HubRelease>(HubUpdateService.DecodeJson(bytes));release.Validate();if(release.Version!="2.0.0")throw new Exception("Version decode failed");}});
   test("update metadata rejects outside repository, HTTP and invalid hashes",()=>{foreach(string url in new[]{"http://github.com/KirrieD/HUB-ReFIXwin11/releases/download/v2/app.zip","https://example.org/app.zip","https://github.com/evil/HUB-ReFIXwin11/releases/download/v2/app.zip","https://github.com/KirrieD/HUB-ReFIXwin11/releases/download/v2/app.zip?token=x"})Reject(()=>HubUpdateService.AssetUrl(url,".zip"));Reject(()=>Release("nohash").Validate());Release(new string('a',64)).Validate();});
   test("update redirect allowlist rejects unrelated hosts and nonHTTPS",()=>{foreach(string url in new[]{"https://evil.example/a","http://release-assets.githubusercontent.com/a","https://github.com/other/repo/releases/download/v2/a.zip","https://release-assets.githubusercontent.com:444/a"})Reject(()=>HubUpdateService.Redirect(new Uri(url)));HubUpdateService.Redirect(new Uri("https://release-assets.githubusercontent.com/github-production-release-asset/a?sig=abc"));});
   test("update package rejects traversal, ADS, device and duplicate paths",()=>{foreach(string path in new[]{"../escape","/absolute","x:stream","dir\\x","nul.txt","foo./a","a//b"})Reject(()=>UpdateEngine.Relative(path));string zip=Path.Combine(root,"bad.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){z.CreateEntry("../escape");}Reject(()=>UpdateEngine.Extract(zip,Path.Combine(root,"bad-stage")));if(File.Exists(Path.Combine(root,"escape")))throw new Exception("Escaped staging");string duplicate=Path.Combine(root,"duplicate.zip");using(var z=ZipFile.Open(duplicate,ZipArchiveMode.Create)){z.CreateEntry("A");z.CreateEntry("a");}Reject(()=>UpdateEngine.Extract(duplicate,Path.Combine(root,"duplicate-stage")));});
   test("verified update applies owned files and preserves unknown files and Setup marker",()=>{var p=Fixture(root,"apply");File.WriteAllText(Path.Combine(p.Target,"settings.json"),"user settings");File.WriteAllText(Path.Combine(p.Target,"installation.json"),"{\"Mode\":\"Setup\",\"Version\":\"1.1.0\",\"Custom\":\"retained\"}");UpdateEngine.Apply(p,null);var marker=UpdateEngine.Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(p.Target,"installation.json")));if(File.ReadAllText(Path.Combine(p.Target,"HUB-ReFIX.Core.exe"))!="new"||File.Exists(Path.Combine(p.Target,"packages/quick-note-1.1.0.zip"))||File.ReadAllText(Path.Combine(p.Target,"settings.json"))!="user settings"||Convert.ToString(marker["Mode"])!="Setup"||Convert.ToString(marker["Version"])!="2.0.0"||Convert.ToString(marker["Custom"])!="retained")throw new Exception("Apply/preservation failed");UpdateEngine.Manifest(p.Target,true);});
   test("failed update rolls every touched file back and preserves user data",()=>{var p=Fixture(root,"rollback");File.WriteAllText(Path.Combine(p.Target,"user.txt"),"keep");string before=UpdateEngine.Hash(Path.Combine(p.Target,"bundle-files.json"));Reject(()=>UpdateEngine.Apply(p,n=>{if(n==3)throw new IOException("Injected copy failure");}));if(File.ReadAllText(Path.Combine(p.Target,"HUB-ReFIX.Core.exe"))!="old"||!File.Exists(Path.Combine(p.Target,"packages/quick-note-1.1.0.zip"))||File.ReadAllText(Path.Combine(p.Target,"user.txt"))!="keep"||UpdateEngine.Hash(Path.Combine(p.Target,"bundle-files.json"))!=before)throw new Exception("Rollback changed old app");UpdateEngine.Manifest(p.Target,true);});
   test("changed prepared payload rejected before touching target",()=>{var p=Fixture(root,"tamper");File.WriteAllText(Path.Combine(p.Stage,"HUB-ReFIX.Core.exe"),"tampered");Reject(()=>UpdateEngine.Apply(p,null));if(File.ReadAllText(Path.Combine(p.Target,"HUB-ReFIX.Core.exe"))!="old")throw new Exception("Target changed");});
   test("new owned files cannot overwrite unknown user files",()=>{var p=Fixture(root,"collision");string unknown=Path.Combine(p.Target,"packages/quick-note-2.0.0.zip");File.WriteAllText(unknown,"user");Reject(()=>UpdateEngine.Apply(p,null));if(File.ReadAllText(unknown)!="user")throw new Exception("User file changed");});
   test("actual portable wrapper and Windows manifest paths extract and apply",()=>{var p=Fixture(root,"wrapped");var m=UpdateEngine.Manifest(p.Stage,true);foreach(var f in m.Files)f.Path=f.Path.Replace('/','\\');File.WriteAllText(Path.Combine(p.Stage,"bundle-files.json"),UpdateEngine.Json().Serialize(m));string zip=Path.Combine(root,"wrapped.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){foreach(string file in Directory.GetFiles(p.Stage,"*",SearchOption.AllDirectories))ZipFileExtensions.CreateEntryFromFile(z,file,"HUB-ReFIXwin11/"+file.Substring(p.Stage.Length+1).Replace('\\','/'));}Directory.Delete(p.Stage,true);UpdateEngine.Extract(zip,p.Stage);p.ManifestHash=UpdateEngine.Hash(Path.Combine(p.Stage,"bundle-files.json"));UpdateEngine.Apply(p,null);UpdateEngine.Manifest(p.Target,true);});
   test("mixed wrapper roots and wrapper traversal or symlinks are rejected",()=>{foreach(string name in new[]{"outside.txt","HUB-ReFIXwin11/../escape","HUB-ReFIXwin11/link"}){string zip=Path.Combine(root,Guid.NewGuid().ToString("N")+".zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){z.CreateEntry("HUB-ReFIXwin11/");var e=z.CreateEntry(name);if(name.EndsWith("link"))e.ExternalAttributes=0xA000<<16;}Reject(()=>UpdateEngine.Extract(zip,Path.Combine(root,Guid.NewGuid().ToString("N"))));}});
   test("new bundle requires configs, catalog and known module packages",()=>{foreach(string required in new[]{"HUB-ReFIX.Core.exe.config","HUB-ReFIX.exe.config","catalog.json","packages/quick-note-2.0.0.zip"}){var p=Fixture(root,"required-"+Guid.NewGuid().ToString("N"));var m=UpdateEngine.Manifest(p.Stage,true);m.Files.RemoveAll(f=>f.Path==required);File.WriteAllText(Path.Combine(p.Stage,"bundle-files.json"),UpdateEngine.Json().Serialize(m));Reject(()=>UpdateEngine.Manifest(p.Stage,true));}});
   test("Setup marker version is restored byte for byte after late failure",()=>{var p=Fixture(root,"marker-rollback");string marker="{\"Mode\":\"Setup\",\"Version\":\"1.1.0\",\"Custom\":7}";File.WriteAllText(Path.Combine(p.Target,"installation.json"),marker);Reject(()=>UpdateEngine.Apply(p,n=>{if(File.ReadAllText(Path.Combine(p.Target,"installation.json"))!=marker)throw new IOException("After marker write");}));if(File.ReadAllText(Path.Combine(p.Target,"installation.json"))!=marker||File.ReadAllText(Path.Combine(p.Target,"HUB-ReFIX.Core.exe"))!="old")throw new Exception("Marker rollback failed");});
   test("overlapping update roots and forged parent path rejected",()=>{var p=Fixture(root,"roots");p.Work=Path.Combine(p.Target,"stage");Reject(()=>UpdateEngine.ValidatePlan(p));p=Fixture(root,"identity");p.ParentPath=Path.Combine(p.Target,"other.exe");Reject(()=>UpdateEngine.ValidatePlan(p));});
   test("helper rejects a reused PID or different parent executable without waiting",()=>{using(var current=Process.GetCurrentProcess()){var p=Fixture(root,"parent-reuse");p.ParentPid=current.Id;p.ParentStartedUtc=current.StartTime.ToUniversalTime().Ticks-1;Reject(()=>UpdateEngine.WaitForParent(p));p.ParentStartedUtc=current.StartTime.ToUniversalTime().Ticks;Reject(()=>UpdateEngine.WaitForParent(p));}});
   test("bundle integrity rejects missing and unlisted files",()=>{var p=Fixture(root,"missing");File.Delete(Path.Combine(p.Stage,"ReFix.Shared.dll"));Reject(()=>UpdateEngine.Manifest(p.Stage,true));var q=Fixture(root,"extra");string zip=Path.Combine(root,"extra.zip");File.WriteAllText(Path.Combine(q.Stage,"unlisted.txt"),"oops");ZipFile.CreateFromDirectory(q.Stage,zip);Reject(()=>UpdateEngine.Extract(zip,Path.Combine(root,"extra-extract")));});
  }finally{try{Directory.Delete(root,true);}catch{}}
 }
 static HubRelease Release(string hash){return new HubRelease{SchemaVersion=1,Version="2.0.0",PackageUrl="https://github.com/KirrieD/HUB-ReFIXwin11/releases/download/v2/app.zip",Sha256=hash,SetupUrl="https://github.com/KirrieD/HUB-ReFIXwin11/releases/download/v2/Setup.exe",SetupSha256=hash};}
 static void Reject(Action action){bool rejected=false;try{action();}catch{rejected=true;}if(!rejected)throw new Exception("Unsafe input accepted");}
 static UpdatePlan Fixture(string root,string name){string target=Path.Combine(root,name,"app"),work=Path.Combine(root,name,"work"),stage=Path.Combine(work,"payload");Directory.CreateDirectory(target);Directory.CreateDirectory(stage);foreach(string file in UpdateEngine.Required){foreach(string dir in new[]{target,stage}){string path=Path.Combine(dir,file);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,dir==target?"old":"new");}}foreach(string dir in new[]{target,stage}){string version=dir==target?"1.1.0":"2.0.0";var modules=new List<object>();foreach(string id in new[]{"quiet-mixer","quick-note"}){string path=Path.Combine(dir,"packages",id+"-"+version+".zip");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,"package "+version);modules.Add(new {Id=id,Version=version,Sha256=UpdateEngine.Hash(path)});}File.WriteAllText(Path.Combine(dir,"catalog.json"),UpdateEngine.Json().Serialize(new{SchemaVersion=1,Modules=modules}));WriteManifest(dir,version);}return new UpdatePlan{SchemaVersion=1,Target=target,Work=work,Stage=stage,Version="2.0.0",ManifestHash=UpdateEngine.Hash(Path.Combine(stage,"bundle-files.json")),ParentPid=123,ParentStartedUtc=123,ParentPath=Path.Combine(target,"HUB-ReFIX.Core.exe")};}
 static void WriteManifest(string root,string version){var m=new BundleManifest{SchemaVersion=1,Version=version,Files=new List<BundleFile>()};foreach(string file in Directory.GetFiles(root,"*",SearchOption.AllDirectories)){string rel=file.Substring(root.Length+1).Replace('\\','/');if(rel=="bundle-files.json")continue;m.Files.Add(new BundleFile{Path=rel,Sha256=UpdateEngine.Hash(file)});}File.WriteAllText(Path.Combine(root,"bundle-files.json"),UpdateEngine.Json().Serialize(m));}
}
